app.get('/api/work-snapshots', async (req, res) => {
  try {
    const remote = wbRemote();
    if (!remote) return res.json({ success: true, snapshots: [], recommended: '', note: 'не на Actions-раннере' });
    // ls-remote is the cheap freshness check; refresh the tree only when the
    // branch really moved (a snapshot push) or every 5 minutes max.
    const heads = await wbRunCmd('git', ['ls-remote', remote, 'refs/heads/work-backup'], 30000);
    const sha = (heads.out.trim().split(/\s+/)[0] || '').trim();
    if (!sha || heads.code !== 0 || !/^[0-9a-f]{40}$/.test(sha)) {
      return res.json({ success: true, snapshots: wbIndex.snapshots || [], recommended: wbIndex.recommended || '', note: 'ветка work-backup пока пустая' });
    }
    if (wbIndex.sha !== sha || !wbIndex.at || (Date.now() - wbIndex.at) > 300000) {
      fs.mkdirSync(WB_CACHE_DIR, { recursive: true });
      if (!fs.existsSync(path.join(WB_CACHE_DIR, 'HEAD'))) {
        const init = await wbRunCmd('git', ['init', '-q', '--bare', WB_CACHE_DIR], 20000);
        if (init.code !== 0) throw new Error('git init: ' + init.out.slice(0, 200));
      }
      const fch = await wbRunCmd('git', ['--git-dir=' + WB_CACHE_DIR, 'fetch', '-q', '--depth=1', '--filter=blob:none', remote, '+refs/heads/work-backup:refs/wb'], 180000);
      if (fch.code !== 0) throw new Error(wbWhy(fch, 'не скачал ветку work-backup'));
      // No -l here, on purpose: the long format needs every blob to print a
      // size, and this fetch is a blob:none partial clone. See wbTreeSizes.
      const tree = await wbRunCmd('git', ['--git-dir=' + WB_CACHE_DIR, 'ls-tree', '-r', 'refs/wb', '--', 'snapshots/'], 60000);
      if (tree.code !== 0) throw new Error(wbWhy(tree, 'не прочитал дерево снапшотов'));
      // stamp -> tree object id, so the sizes can be asked for per snapshot.
      const tops = await wbRunCmd('git', ['--git-dir=' + WB_CACHE_DIR, 'ls-tree', 'refs/wb:snapshots'], 30000);
      const stampTree = new Map();
      if (tops.code === 0) {
        for (const line of tops.out.split('\n')) {
          const m = line.match(/^040000 tree ([0-9a-f]{40})\s+(\S+)$/);
          if (m) stampTree.set(m[2], m[1]);
        }
      }
      const repo = process.env.GITHUB_REPOSITORY || '';
      // One request per snapshot (there are a handful), then cached by tree id.
      const sizesByStamp = new Map();
      for (const [stamp, sha2] of stampTree) {
        if (repo) sizesByStamp.set(stamp, await wbTreeSizes(repo, stamp, sha2));
      }
      const snaps = new Map();
      for (const line of tree.out.split('\n')) {
        const m = line.match(/^\S+ blob +\S+\t?snapshots\/([^/]+)\/(.+)$/);
        if (!m) continue;
        const stamp = m[1], rel = m[2];
        let s = snaps.get(stamp);
        if (!s) { s = { stamp, repos: new Map(), extras: 0, chats: 0, chatNames: [], settings: false, sessions: false, total: 0, sized: 0 }; snaps.set(stamp, s); }
        const sizes = sizesByStamp.get(stamp);
        const size = sizes && sizes.has('snapshots/' + stamp + '/' + rel) ? sizes.get('snapshots/' + stamp + '/' + rel) : null;
        // Presence is the reliable signal for "this repo was really packed":
        // backup-work only commits a bundle/archive when it has content, so a
        // blob here means a non-empty repo. Sizes may be unknown; that must
        // never decide what the panel offers to restore.
        s.sized += size == null ? 0 : 1;
        s.total += size || 0;
        const base = rel.split('/').pop();
        const dir = rel.slice(0, -(base.length + 1));
        if (base === 'repo.bundle' || base === 'worktree.tar.gz') {
          const e = s.repos.get(dir) || { rel: dir, bytes: 0, kind: '', sized: 0 };
          e.sized += size == null ? 0 : 1;
          e.bytes += size || 0;
          e.kind = base === 'repo.bundle' ? 'git' : 'архив';
          s.repos.set(dir, e);
        } else if (base === 'wip.patch' || base === 'untracked.tar.gz') {
          s.extras += size || 0;
        } else if (rel.startsWith('opencode/chats/') && base.endsWith('.json')) {
          s.chats += 1;
          s.chatNames.push(base.replace(/\.json$/, ''));
        } else if (rel.startsWith('opencode/settings/') && base !== 'manifest.json') {
          s.settings = true;
        } else if (rel.startsWith('descriptors/')) {
          // Terminal descriptors and the TUI screen snapshots beside them: what
          // makes a reopened terminal show the last known screen instead of a
          // blank one. Ticked separately from the chat sessions, because it is
          // a different thing to want back.
          s.sessions = true;
        }
      }
      const list = [...snaps.values()].map(s => {
        const active = s.repos.size > 0 || s.chats > 0 || s.settings || s.sessions;
        return {
          stamp: s.stamp,
          // every repo whose bundle/archive is in the tree, size unknown or not
          repos: [...s.repos.values()].sort((a, b) => a.rel.localeCompare(b.rel)),
          extrasMb: Math.round(s.extras / 104857.6) / 10,
          chats: s.chats, chatNames: s.chatNames.sort(), settings: s.settings,
          sessions: s.sessions, active,
          totalMb: Math.round(s.total / 104857.6) / 10,
          sized: s.sized > 0
        };
      });
      list.sort((a, b) => b.stamp.localeCompare(a.stamp));
      // "Всегда самые новые; если новые пустые — последние, где что-то делали":
      // рекомендация = новейший снапшот с реальной активностью (репо или чаты
      // opencode или настройки), а не просто самый свежий по времени.
      const recommended = (list.find(s => s.active) || { stamp: '' }).stamp;
      wbIndex = { sha, at: Date.now(), snapshots: list, recommended };
    }
    res.json({ success: true, snapshots: wbIndex.snapshots, recommended: wbIndex.recommended });
  } catch (e) {
    res.json({ success: false, error: 'не прочитал work-backup: ' + e.message });
  }
});

app.post('/api/work-snapshots/restore', express.json(), (req, res) => {
  try {
    const stamp = String((req.body && req.body.snapshot) || '').trim();
    if (!stamp || !/^[A-Za-z0-9._:-]+$/.test(stamp) || stamp.includes('..') || stamp.includes('/')) {
      return res.json({ success: false, error: 'некорректное имя снапшота' });
    }
    // What the user ticked. An absent field means "yes": the page sends every
    // checkbox, and a hand-written POST from the terminal must keep restoring
    // everything rather than nothing.
    const body = req.body || {};
    const yes = v => v === undefined || v === null || v === true || v === 1 || v === '1';
    const wantChats = yes(body.chats);
    const wantSettings = yes(body.settings);
    const wantFiles = yes(body.files);
    const wantSessions = yes(body.sessions);
    // repos: a list of `rel` paths, or absent / empty / ['*'] for all of them.
    let repos = '*';
    if (Array.isArray(body.repos) && body.repos.length) {
      const picked = body.repos
        .map(r => String(r == null ? '' : r).trim())
        .filter(r => r && r !== '*' && r.length <= 400
          && !r.includes('\0') && !/[\n\r]/.test(r) && !r.startsWith('/') && !r.split('/').includes('..'));
      repos = picked.length ? picked.join('\n') : '';
      if (!picked.length && body.repos.some(r => String(r) === '*')) repos = '*';
    }
    if (wbRestore.running) return res.json({ success: false, error: 'восстановление уже идёт' });
    const token = runnerToken();
    if (!token) return res.json({ success: false, error: 'нет токена GitHub' });
    if (!fs.existsSync(RESTORE_WORK_SH)) return res.json({ success: false, error: 'нет скрипта восстановления' });
    wbRestore = { running: true, startedAt: Date.now(), doneAt: 0, code: null, tail: [] };
    const pickedList = repos === '*' ? 'все' : (repos === '' ? 'нет' : repos.split('\n').join(', '));
    wbPushTail('♻ восстановление из snapshots/' + stamp + '\n');
    wbPushTail('   выбрано: репо=[' + pickedList + ']' +
      ' чаты=' + (wantChats ? 'да' : 'нет') +
      ' настройки=' + (wantSettings ? 'да' : 'нет') +
      ' файлы=' + (wantFiles ? 'да' : 'нет') +
      ' сессии=' + (wantSessions ? 'да' : 'нет') + '\n');
    const env = Object.assign({}, process.env, {
      GH_TOKEN: token,
      GITHUB_TOKEN: token,
      GITHUB_REPOSITORY: process.env.GITHUB_REPOSITORY || '',
      HUB_LOGS: LOG_DIR,
      WORK_BACKUP_ROOT: HOME,
      WORK_BACKUP_RESTORE_EXISTING: '1',
      WORK_BACKUP_SNAPSHOT: 'snapshots/' + stamp,
      WORK_BACKUP_ONLY_REPOS: repos,
      WORK_BACKUP_SKIP_CHATS: wantChats ? '0' : '1',
      WORK_BACKUP_SKIP_SETTINGS: wantSettings ? '0' : '1',
      WORK_BACKUP_SKIP_FILES: wantFiles ? '0' : '1',
      WORK_BACKUP_SKIP_SESSIONS: wantSessions ? '0' : '1'
    });
    const child = spawn('bash', [RESTORE_WORK_SH], { env, stdio: ['ignore', 'pipe', 'pipe'] });
    child.stdout.on('data', d => { process.stdout.write(d); wbPushTail(d); });
    child.stderr.on('data', d => { wbPushTail(d); });
    const timer = setTimeout(() => { try { child.kill('SIGKILL'); } catch {} ; wbPushTail('⏱ таймаут 40 минут — прервал'); }, 40 * 60000);
    child.on('error', e => { clearTimeout(timer); wbRestore.running = false; wbRestore.doneAt = Date.now(); wbRestore.code = -1; wbPushTail('ошибка запуска: ' + e.message); });
    child.on('close', code => { clearTimeout(timer); wbRestore.running = false; wbRestore.doneAt = Date.now(); wbRestore.code = code; wbPushTail(code === 0 ? '✅ восстановление завершено' : ('❌ скрипт завершился с кодом ' + code)); });
    res.json({ success: true });
  } catch (e) {
    res.json({ success: false, error: e.message });
  }
});

app.get('/api/work-snapshots/restore/status', (req, res) => {
  const t = wbRestore;
  res.json({
    success: true,
    running: t.running,
    startedAt: t.startedAt || 0,
    doneAt: t.doneAt || 0,
    code: t.code,
    elapsed: t.startedAt ? Math.round((((t.running ? Date.now() : t.doneAt) || Date.now()) - t.startedAt) / 1000) : 0,
    tail: t.tail.slice(-80)
  });
});

