const REPO = 'sj0404-collab/zen-panel';
const GH = 'https://api.github.com';
const $ = id => document.getElementById(id);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g,
  c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
// ── the journal ──
// Timestamped, and capped. A log without a clock makes "it has been stuck for
// four minutes" indistinguishable from "it did nothing at all", and a log that
// only grows is a log nobody scrolls. The last few hundred lines are the ones
// that describe what is happening right now.
const LOG_MAX = 500;
// The journal is temporary, so it stays collapsed: one status line carries
// what it is doing right now, and nothing else is visible until an error
// (opened automatically — a failure must never hide) or the user's press.
const LOG_KEY = 'hub_journal';
let logOpen = false;
function logSetOpen(v) {
  logOpen = !!v;
  const el = $('log'), t = $('log-toggle');
  if (el) el.className = logOpen ? 'log open' : 'log';
  if (t) {
    t.setAttribute('aria-expanded', logOpen ? 'true' : 'false');
    $('log-toggle-lbl').textContent = logOpen ? 'Журнал ▲' : 'Журнал ▸';
  }
  try { localStorage.setItem(LOG_KEY, logOpen ? '1' : ''); } catch (e) {}
}
function hhmmss(d) {
  return [d.getHours(), d.getMinutes(), d.getSeconds()]
    .map(n => String(n).padStart(2, '0')).join(':');
}
function log(m, cls) {
  const el = $('log');
  if (!el) return;
  const line = document.createElement('div');
  if (cls) line.className = cls;
  const ts = document.createElement('span');
  ts.className = 'ts';
  ts.textContent = hhmmss(new Date());
  line.appendChild(ts);
  line.appendChild(document.createTextNode(String(m == null ? '' : m)));
  el.appendChild(line);
  while (el.childElementCount > LOG_MAX) el.removeChild(el.firstChild);
  // The status line mirrors the newest entry and the line count, so a
  // collapsed journal still answers "what is it doing".
  const lastEl = $('log-last');
