async function listActiveRuns(token, predicate) {
  const active = [];
  for (let page = 1; page <= 5; page++) {
    const r = await api(`/repos/${REPO}/actions/runs?per_page=100&page=${page}`, token);
    const runs = r && r.workflow_runs;
    if (!runs || !runs.length) break;
    for (const run of runs) {
      if (isActiveRun(run) && (!predicate || predicate(run))) active.push(run);
    }
    if (runs.length < 100) break;
  }
  return active;
}
async function cancelCurrentRun(token) {
  const runs = await listActiveRuns(token, isHubRun);
  const ids = [];
  let failed = 0;
  for (const run of runs) {
    try {
      await api(`/repos/${REPO}/actions/runs/${run.id}/cancel`, token, { method: 'POST' });
      ids.push(run.id);
    } catch (e) {
      if (!/HTTP 409/.test(e && e.message || '')) failed++;
    }
  }
  if (failed) throw new Error('GitHub не принял остановку старого запуска.');
  return ids;
}
async function waitForRunsToStop(token, ids, sleepMs, attempts) {
  const pending = new Set((ids || []).map(String));
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pause = sleepMs == null ? 3000 : sleepMs;
  const limit = attempts == null ? 400 : attempts;
  for (let i = 0; pending.size && i < limit; i++) {
    await sleep(pause);
    const r = await api(`/repos/${REPO}/actions/runs?per_page=50`, token);
    const alive = new Set((r && r.workflow_runs || []).filter(isActiveRun).map(x => String(x.id)));
    for (const id of Array.from(pending)) if (!alive.has(id)) pending.delete(id);
  }
  if (pending.size) throw new Error('Старый запуск ещё не остановлен GitHub. Повторите перезапуск через минуту.');
  return true;
}
async function cancelAndWait(token) {
  const ids = await cancelCurrentRun(token);
  if (ids.length) await waitForRunsToStop(token, ids);
  return ids.length;
}
