// reserve that does not exist, and the actual reason is always included. When
// the spare entrance was tried and still failed, the message says so and
// points at the GitHub token that unlocks it (or at a runner restart).
function describeBaseFailure(bases, errors, zt, spareTried) {
  const reasons = [];
  for (const e of errors) if (e && e.reason && reasons.indexOf(e.reason) < 0) reasons.push(e.reason);
  const detail = reasons.join('; ') || 'нет ответа';
  if (spareTried) {
